'use strict';
let appSection='history',philosophyAtlasData={range:[-650,1831],phases:[],nodes:[]};
let philosophyState={year:-399,entry:'ph-prehistory-socrates',kind:'all',query:'',zoom:true},philosophyTimer=null,philosophyFrame=null,philosophyPending=null,philosophyReturnToReader=false;
const philosophyKinds=[['all','全部条目'],['person','人物生平／活动'],['work','著作与版本'],['event','论争与传播']];
const isPhilosophyView=()=>appSection==='philosophy';
const philosophyYearIndex=year=>year<0?year:year-1;
const philosophyIndexYear=index=>index<0?index:index+1;
function philosophyDate(year){return year<0?'前'+Math.abs(year)+'年':'公元'+year+'年';}
function philosophySpan(span){return span[0]===span[1]?philosophyDate(span[0]):philosophyDate(span[0])+'—'+philosophyDate(span[1]);}
function philosophyNode(id){return philosophyAtlasData.nodes.find(n=>n.id===id);}
function philosophyPhase(year=philosophyState.year){return year===0?null:philosophyAtlasData.phases.find(p=>p.range[0]<=year&&year<=p.range[1]);}
function philosophyDomain(){return philosophyState.zoom?philosophyPhase().range:philosophyAtlasData.range;}
function philosophyPercent(year,domain=philosophyDomain()){return 100*(philosophyYearIndex(year)-philosophyYearIndex(domain[0]))/(philosophyYearIndex(domain[1])-philosophyYearIndex(domain[0]));}
function philosophyMatches(node){return (philosophyState.kind==='all'||node.kind===philosophyState.kind)&&(!philosophyState.query||[node.title,node.summary,...(node.people||[]),...(node.sections||[]).map(s=>s.text)].join(' ').toLocaleLowerCase().includes(philosophyState.query.toLocaleLowerCase()));}
function philosophyVisibleNodes(){const phase=philosophyPhase();return philosophyAtlasData.nodes.filter(n=>philosophyMatches(n)&&(!philosophyState.zoom||philosophyState.query||n.phaseId===phase.id));}
function validPhilosophyPosition(value){return value&&value.version===1&&Number.isInteger(value.year)&&value.year!==0&&value.year>=philosophyAtlasData.range[0]&&value.year<=philosophyAtlasData.range[1]&&philosophyNode(value.entry)&&philosophyKinds.some(k=>k[0]===value.kind)&&typeof value.query==='string'&&value.query.length<=200&&typeof value.zoom==='boolean';}
function rememberPhilosophyPosition(){try{localStorage.setItem('yanguang:philosophy-position:v1',JSON.stringify({version:1,...philosophyState}));}catch{/* Reading remains available without storage. */}}
function rememberHistoryPosition(){if(!state?.event)return;const params=new URLSearchParams();params.set('event',state.event);params.set('module',state.module);params.set('route',state.route);params.set(isOT()?'node':'year',state.year);params.set('compare',state.comparison?'1':'0');try{localStorage.setItem('yanguang:history-position:v1',params.toString());}catch{}}
function restoreHistoryPosition(params){if(['module','event','year','node','route'].some(key=>params.has(key)))return;try{const saved=new URLSearchParams(localStorage.getItem('yanguang:history-position:v1')||'');if(!atlas.events.some(e=>e.id===saved.get('event')))return;for(const [key,value] of saved)if(['module','event','route','year','node','compare'].includes(key))params.set(key,value);}catch{}}
function philosophyURL(node=philosophyNode(philosophyState.entry)){const url=new URL(location.href);url.searchParams.set('section','philosophy');url.searchParams.set('phView',philosophyView);if(philosophyView==='guide'&&typeof guidePersonId!=='undefined'&&$('#philosophy-person-dialog')?.open){url.searchParams.set('phGuide',guidePersonId);url.searchParams.set('phGuideTab',guidePersonTab);}else{url.searchParams.delete('phGuide');url.searchParams.delete('phGuideTab');}url.searchParams.set('phYear',philosophyState.year);url.searchParams.set('phEntry',node.id);url.searchParams.delete('read');url.searchParams.delete('readArea');return url;}
function syncPhilosophyURL(){if(isPhilosophyView())history.replaceState(null,'',philosophyURL());}
function setAppSection(section){if(!['history','philosophy'].includes(section))return;if(typeof saveGuideReading==='function')saveGuideReading();stop();stopPhilosophy();if(section==='philosophy'){rememberHistoryPosition();appSection='philosophy';renderPhilosophyAtlas();}else{rememberPhilosophyPosition();appSection='history';}
 document.body.classList.toggle('philosophy-mode',isPhilosophyView());$('.workspace').hidden=isPhilosophyView();$('#timeline-dock').hidden=isPhilosophyView();$('#history-section-nav').hidden=isPhilosophyView();$('#philosophy-workspace').hidden=!isPhilosophyView();$('#philosophy-timeline').hidden=!isPhilosophyView();document.querySelectorAll('[data-app-section]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.appSection===appSection)));
 document.title=isPhilosophyView()?'言光 · 西方哲学史':`言光 · ${moduleConfig().name}交互地图`;
 if(isPhilosophyView()){syncPhilosophyURL();rememberPhilosophyPosition();}else{const url=new URL(location.href);for(const key of ['section','phView','phYear','phEntry','phGuide','phGuideTab','read','readArea'])url.searchParams.delete(key);history.replaceState(null,'',url);requestAnimationFrame(()=>{renderComparison();updateCamera();});}
}
function openPhilosophyAtlas({year=null,entry=null,fromReader=false}={}){setPhilosophyView(entry?'timeline':'guide',false);if(fromReader)philosophyReturnToReader=true;else if(!isPhilosophyView())philosophyReturnToReader=false;$('#philosophy-return-history').textContent=philosophyReturnToReader?'返回刚才阅读':'返回历史主线';if(philosophyNode(entry)){philosophyState.entry=entry;if(year===null)year=philosophyNode(entry).anchor;}if(Number.isInteger(year)&&year!==0&&year>=-650&&year<=1831){philosophyState.year=year;if(!entry)philosophyState.entry=philosophyNearest(year)?.id||philosophyState.entry;}setAppSection('philosophy');}
function philosophyNearest(year){const eligible=philosophyAtlasData.nodes.filter(philosophyMatches);return eligible.filter(n=>n.anchor<=year).at(-1)||eligible[0]||philosophyNode(philosophyState.entry);}
function browsePhilosophyYear(year){if(!Number.isInteger(year)||year===0){$('#philosophy-year-input').value=philosophyState.year;$('#philosophy-year-status').textContent='请输入整数公历年；公元前使用负数，没有公历零年。';return;}year=Math.round(Math.max(-650,Math.min(1831,year)));philosophyState.year=year;philosophyState.entry=philosophyNearest(year).id;$('#philosophy-year-status').textContent='';renderPhilosophyAtlas();syncPhilosophyURL();rememberPhilosophyPosition();}
function selectPhilosophyNode(id){const node=philosophyNode(id);if(!node)return;stopPhilosophy();philosophyState.entry=id;philosophyState.year=node.anchor;renderPhilosophyAtlas();syncPhilosophyURL();rememberPhilosophyPosition();if(innerWidth<=760)$('#philosophy-entry').scrollIntoView({block:'start'});}
function selectPhilosophyPhase(id){const phase=philosophyAtlasData.phases.find(p=>p.id===id);if(!phase)return;stopPhilosophy();philosophyState.zoom=true;const node=philosophyAtlasData.nodes.find(n=>n.phaseId===id&&philosophyMatches(n));philosophyState.year=node?.anchor||phase.range[0];if(node)philosophyState.entry=node.id;renderPhilosophyAtlas();syncPhilosophyURL();rememberPhilosophyPosition();if(philosophyView==='overview')scrollPhilosophyOverviewPhase(id);if(philosophyView==='guide')scrollGuidePhase(id);}
function stopPhilosophy(){clearInterval(philosophyTimer);philosophyTimer=null;if($('#philosophy-play')){$('#philosophy-play').textContent='▶';$('#philosophy-play').setAttribute('aria-label','播放哲学时间轴');}}
function stepPhilosophy(delta){const entries=philosophyVisibleNodes(),index=entries.findIndex(n=>n.id===philosophyState.entry),next=index<0?0:index+delta;if(entries[next]){const playing=Boolean(philosophyTimer);selectPhilosophyNode(entries[next].id);if(playing)startPhilosophy(false);}else stopPhilosophy();}
function startPhilosophy(restart=true){if(philosophyTimer)return;const entries=philosophyVisibleNodes();if(!entries.length)return;if(restart&&entries.length>1&&entries.at(-1).id===philosophyState.entry){philosophyState.entry=entries[0].id;philosophyState.year=entries[0].anchor;renderPhilosophyAtlas();syncPhilosophyURL();}philosophyTimer=setInterval(()=>stepPhilosophy(1),2400);$('#philosophy-play').textContent='Ⅱ';$('#philosophy-play').setAttribute('aria-label','暂停哲学时间轴');}
function philosophyReadRef(ref){stopPhilosophy();if(!ref)return;openComparisonReader(ref.kind==='culture'?'culture':'events');focusReaderEntity(ref.kind,ref.id);const target=readerEntityElement(ref.kind,ref.id);const body=target?.querySelector('.reader-entry-body,.reader-work-body,.reader-profile-body,.culture-article-body');if(body)body.open=true;}
function openPhilosophyRelations(id){if((comparisonReaderData.cultureNetworkLanes||[]).some(l=>l.personIds.includes(id))){philosophyReadRef({kind:'culture',id:'network-'+id});return;}const figure=treeFigureMap.get(id);if(!figure?.primaryNodeId)return;philosophyOpenRaw(figure.primaryNodeId);const bio=$('#reader-content .tree-person-details'),relations=$('#reader-content .tree-relations-details');if(bio)bio.open=true;if(relations){relations.open=true;relations.scrollIntoView({block:'start'});}}
