function philosophyLocation(node){const block=historyEl('details',null,'philosophy-location');block.append(historyEl('summary','地点与传播背景 · '+node.place));const {lon,lat}=node.coordinates,[x,y]=project(lon,lat),svg=svgNode('svg',{viewBox:`${x-145} ${y-100} 290 200`,role:'img','aria-label':node.place+'的现代地理参照'});for(const path of $('#overview-land').children)svg.append(path.cloneNode(true));svg.append(svgNode('circle',{cx:x,cy:y,r:3,fill:'#985637'}));block.append(svg,historyEl('p','地点参照：'+node.place+'。现代海岸与近似坐标用于定位，不表示精确古代疆域或写作地址。'));return block;}
function renderPhilosophyEntry(node){const root=$('#philosophy-entry');if(root.dataset.node===node.id)return;root.dataset.node=node.id;root.replaceChildren();root.scrollTop=0;const article=historyEl('article',null,'philosophy-entry-content');article.dataset.philosophyEntry=node.id;article.append(historyEl('p',philosophyKinds.find(k=>k[0]===node.kind)[1]+' · 编选导读','reading-kind-label'),historyEl('h2',node.title),historyEl('p',node.dateLabel,'philosophy-entry-date'));
 const spanLabel=node.kind==='person'?(node.dateKind==='activity'?'已知作品／活动期':'生平范围'):'所涉年代';article.append(historyEl('p',spanLabel+'：'+philosophySpan(node.range),'philosophy-entry-meta'));if(node.range[1]>1831)article.append(historyEl('small','本轴显示至1831年；完整生平的后续年份保留在标签中。'));
 if(node.personId){article.append(philosophyPersonGallery(node.personId,{portraitsOnly:true}));if(node.personId==='plato')article.append(cultureFigure('plato-bust'));}if(node.imageId)article.append(cultureFigure(node.imageId));if(node.readRef?.id.startsWith('work-'))article.append(philosophyGallery(philosophyGalleryData.filter(i=>i.workIds.includes(node.readRef.id)).map(i=>i.id)));
 article.append(historyEl('p',node.summary,'philosophy-entry-summary'));const body=historyEl('details',null,'philosophy-entry-body');body.append(historyEl('summary','展开论述与阅读提示'));for(const section of node.sections)if(section.text!==node.summary)body.append(historyEl('h3',section.title),historyEl('p',section.text));body.append(historyEl('p',node.editorial));article.append(body);
 const actions=historyEl('div',null,'philosophy-entry-actions');if(node.readRef)actions.append(libraryButton('阅读完整资料 ↗',()=>philosophyReadRef(node.readRef),'library-primary'));if(node.personId&&((comparisonReaderData.cultureNetworkLanes||[]).some(l=>l.personIds.includes(node.personId))||philosophyTreeData.relations.some(r=>r.fromId===node.personId||r.toId===node.personId)))actions.append(libraryButton('查看思想关系',()=>openPhilosophyRelations(node.personId)));
 if(node.rawRef)actions.append(libraryButton('核对原始笔记',()=>philosophyOpenRaw(node.rawRef)));actions.append(libraryButton('记住此处',()=>{rememberPhilosophyPosition();$('#philosophy-save-status').textContent='已保存哲学浏览位置';}),libraryButton('复制此节点链接',async()=>{try{await navigator.clipboard.writeText(philosophyURL().href);$('#philosophy-save-status').textContent='哲学节点链接已复制';}catch{$('#philosophy-save-status').textContent='可在条目末尾选中链接复制';let field=$('#philosophy-copy-link');if(!field){field=historyEl('input');field.id='philosophy-copy-link';field.type='text';field.readOnly=true;field.setAttribute('aria-label','哲学节点链接');article.append(field);}field.value=philosophyURL().href;field.focus();field.select();}}));article.append(actions,readerSources(node));if(node.coordinates&&node.place)article.append(philosophyLocation(node));root.append(article);}
function renderPhilosophyPlot(nodes,domain){const root=$('#philosophy-plot');root.replaceChildren();root.append(historyEl('p','带状区间与定位年分别阅读；人物定位采用代表活动年，约年详见节点。','philosophy-plot-note'));
 for(const [kind,title] of philosophyKinds.slice(1)){const section=historyEl('section',null,'philosophy-track');section.dataset.philosophyTrack=kind;section.append(historyEl('h3',title));const entries=nodes.filter(n=>n.kind===kind);if(!entries.length)section.append(historyEl('p','本范围暂无匹配条目。','philosophy-track-empty'));for(const node of entries){const row=historyEl('div',null,'philosophy-track-row'),label=libraryButton(node.title,()=>selectPhilosophyNode(node.id),'philosophy-track-label');label.title=node.title+' · '+node.dateLabel;const rail=historyEl('div',null,'philosophy-track-rail'),bar=libraryButton('',()=>selectPhilosophyNode(node.id),'philosophy-span kind-'+kind);bar.dataset.philosophyNode=node.id;bar.title=node.title+' · '+node.dateLabel;bar.setAttribute('aria-label',bar.title);const start=Math.max(domain[0],node.range[0]),end=Math.min(domain[1],node.range[1]);bar.style.left=Math.max(0,philosophyPercent(start,domain))+'%';bar.style.width=Math.max(.7,philosophyPercent(end,domain)-philosophyPercent(start,domain))+'%';bar.classList.toggle('approximate',node.dateKind.includes('approximate')||node.dateKind==='activity');bar.classList.toggle('clipped-start',node.range[0]<domain[0]);bar.classList.toggle('clipped-end',node.range[1]>domain[1]);const cursor=historyEl('span',null,'philosophy-track-cursor');cursor.setAttribute('aria-hidden','true');rail.append(bar,cursor);row.append(label,rail);section.append(row);}root.append(section);}
}
function renderPhilosophyRail(nodes,domain){const [lo,hi]=domain,range=$('#philosophy-year-range');range.min=philosophyYearIndex(lo);range.max=philosophyYearIndex(hi);range.value=philosophyYearIndex(philosophyState.year);range.setAttribute('aria-valuetext',philosophyDate(philosophyState.year));$('#philosophy-axis-range').textContent=philosophySpan(domain);$('#philosophy-axis-zoom').textContent=philosophyState.zoom?'全史概览 ↙':'放大当前阶段 ↗';$('#philosophy-axis-zoom').setAttribute('aria-pressed',String(philosophyState.zoom));
 const key=domain.join(':')+':'+philosophyState.kind+':'+philosophyState.query;if($('#philosophy-axis-bands').dataset.key!==key){$('#philosophy-axis-bands').dataset.key=key;$('#philosophy-axis-bands').replaceChildren();$('#philosophy-axis-markers').replaceChildren();$('#philosophy-axis-ticks').replaceChildren();for(const phase of philosophyAtlasData.phases){const start=Math.max(lo,phase.range[0]),end=Math.min(hi,phase.range[1]);if(end<start)continue;const span=historyEl('span',phase.title,'philosophy-axis-band');span.style.left=philosophyPercent(start,domain)+'%';span.style.width=Math.max(.5,philosophyPercent(end,domain)-philosophyPercent(start,domain))+'%';span.style.background=phase.color;$('#philosophy-axis-bands').append(span);}const groups=new Map();for(const node of nodes)if(node.anchor>=lo&&node.anchor<=hi){if(!groups.has(node.anchor))groups.set(node.anchor,[]);groups.get(node.anchor).push(node);}for(const [year,group] of groups){const marker=libraryButton('',()=>{const index=group.findIndex(n=>n.id===philosophyState.entry);selectPhilosophyNode(group[(index+1)%group.length].id);},'philosophy-axis-marker');marker.dataset.philosophyYear=year;marker.style.left=philosophyPercent(year,domain)+'%';marker.title=philosophyDate(year)+' · '+group.map(n=>n.title).join('；');marker.setAttribute('aria-label',marker.title);$('#philosophy-axis-markers').append(marker);}const step=hi-lo>600?500:hi-lo>200?100:hi-lo>60?25:10;const ticks=[lo];for(let year=Math.ceil(lo/step)*step;year<hi;year+=step)if(year!==0&&year-lo>(hi-lo)*.12&&hi-year>(hi-lo)*.12)ticks.push(year);ticks.push(hi);for(const year of ticks){const span=historyEl('span',year<0?'前'+Math.abs(year):String(year));span.style.left=philosophyPercent(year,domain)+'%';$('#philosophy-axis-ticks').append(span);}}
 $('#philosophy-axis-cursor').style.left=philosophyPercent(philosophyState.year,domain)+'%';$('#philosophy-axis-current').textContent=philosophyDate(philosophyState.year);$('#philosophy-year-input').value=philosophyState.year;document.querySelectorAll('[data-philosophy-year]').forEach(b=>b.classList.toggle('active',Number(b.dataset.philosophyYear)===philosophyState.year));}
function renderPhilosophyAtlas(){if(!philosophyAtlasData.nodes.length)return;const phase=philosophyPhase(),node=philosophyNode(philosophyState.entry),entries=philosophyVisibleNodes(),domain=philosophyDomain();$('#philosophy-phase-title').textContent=phase.title;$('#philosophy-phase-range').textContent=philosophySpan(phase.range);$('#philosophy-phase-intro').textContent=phase.intro;$('#philosophy-browse-context').textContent='浏览 '+philosophyDate(philosophyState.year)+' · 所选条目定位 '+philosophyDate(node.anchor);$('#philosophy-result-count').textContent=`${entries.length} 条 · ${philosophyState.query?'关键词检索覆盖全轴':philosophyState.zoom?'本阶段资料':'全史资料'}`;
 const key=phase.id+':'+philosophyState.kind+':'+philosophyState.query+':'+philosophyState.zoom;if($('#philosophy-node-list').dataset.key!==key){$('#philosophy-node-list').dataset.key=key;$('#philosophy-node-list').replaceChildren();for(const item of entries){const button=libraryButton('',()=>selectPhilosophyNode(item.id),'philosophy-list-item');button.dataset.philosophyList=item.id;button.append(historyEl('small',philosophyDate(item.anchor)+' · '+philosophyKinds.find(k=>k[0]===item.kind)[1]),historyEl('strong',item.title));$('#philosophy-node-list').append(button);}if(!entries.length)$('#philosophy-node-list').append(historyEl('p','没有匹配条目，可清除检索或选择全部类型。','reader-empty'));const plotted=entries.filter(n=>n.range[1]>=domain[0]&&n.range[0]<=domain[1]);renderPhilosophyPlot(plotted,domain);}
 document.querySelectorAll('[data-philosophy-list],[data-philosophy-node]').forEach(button=>{const selected=(button.dataset.philosophyList||button.dataset.philosophyNode)===node.id;button.setAttribute('aria-pressed',String(selected));});document.querySelectorAll('[data-philosophy-phase]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.philosophyPhase===phase.id)));document.querySelectorAll('.philosophy-track-cursor').forEach(c=>c.style.left=philosophyPercent(philosophyState.year,domain)+'%');renderPhilosophyEntry(node);renderPhilosophyRail(philosophyAtlasData.nodes.filter(philosophyMatches),domain);$('#philosophy-kind').value=philosophyState.kind;$('#philosophy-search').value=philosophyState.query;const index=entries.findIndex(n=>n.id===node.id);$('#philosophy-previous').disabled=!entries.length||index<=0;$('#philosophy-next').disabled=!entries.length||index>=entries.length-1;$('#philosophy-play').disabled=!entries.length;renderPhilosophyOverviewSelection();if(typeof renderGuideContext==='function')renderGuideContext();}
function handlePhilosophyKey(event){if(philosophyView!=='timeline')return;if(/INPUT|TEXTAREA|SELECT|BUTTON/.test(document.activeElement.tagName)||document.querySelector('dialog[open]'))return;if(event.key==='ArrowLeft'){event.preventDefault();stepPhilosophy(-1);}else if(event.key==='ArrowRight'){event.preventDefault();stepPhilosophy(1);}else if(event.code==='Space'){event.preventDefault();if(philosophyTimer)stopPhilosophy();else startPhilosophy();}}
function initPhilosophyAtlas(data,params){philosophyAtlasData=data;try{const saved=JSON.parse(localStorage.getItem('yanguang:philosophy-position:v1'));if(validPhilosophyPosition(saved)){const {version,...position}=saved;philosophyState=position;}}catch{}
 const entry=philosophyNode(params.get('phEntry')),year=Number(params.get('phYear'));if(entry)philosophyState.entry=entry.id;if(params.has('phYear')&&year!==0&&Number.isInteger(year)&&year>=-650&&year<=1831)philosophyState.year=year;else if(entry)philosophyState.year=entry.anchor;
 $('#philosophy-editorial').textContent=data.editorial;for(const phase of data.phases){const button=libraryButton(phase.title,()=>selectPhilosophyPhase(phase.id),'philosophy-phase-button');button.dataset.philosophyPhase=phase.id;button.title=philosophySpan(phase.range)+' · '+phase.short;$('#philosophy-phase-tabs').append(button);}for(const [id,title] of philosophyKinds)$('#philosophy-kind').append(new Option(title,id));
 initPhilosophyOverview(params);$('#sources-button').addEventListener('click',stopPhilosophy);document.querySelectorAll('[data-app-section]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.appSection==='philosophy')setPhilosophyView('guide',false);setAppSection(b.dataset.appSection);}));$('#philosophy-kind').addEventListener('change',e=>{stopPhilosophy();philosophyState.kind=e.target.value;renderPhilosophyAtlas();rememberPhilosophyPosition();});$('#philosophy-search').addEventListener('input',e=>{stopPhilosophy();philosophyState.query=e.target.value.trim().slice(0,200);renderPhilosophyAtlas();rememberPhilosophyPosition();});$('#philosophy-clear').addEventListener('click',()=>{philosophyState.query='';philosophyState.kind='all';renderPhilosophyAtlas();rememberPhilosophyPosition();});$('#philosophy-axis-zoom').addEventListener('click',()=>{philosophyState.zoom=!philosophyState.zoom;renderPhilosophyAtlas();rememberPhilosophyPosition();});$('#philosophy-year-input').addEventListener('change',e=>{stopPhilosophy();browsePhilosophyYear(e.target.value===''?NaN:Number(e.target.value));});
 const flush=()=>{philosophyFrame=null;if(philosophyPending!==null){const value=philosophyPending;philosophyPending=null;browsePhilosophyYear(philosophyIndexYear(value));}};$('#philosophy-year-range').addEventListener('input',e=>{stopPhilosophy();philosophyPending=Number(e.target.value);if(philosophyFrame===null)philosophyFrame=requestAnimationFrame(flush);});$('#philosophy-year-range').addEventListener('change',()=>{if(philosophyFrame!==null)cancelAnimationFrame(philosophyFrame);flush();});$('#philosophy-previous').addEventListener('click',()=>stepPhilosophy(-1));$('#philosophy-next').addEventListener('click',()=>stepPhilosophy(1));$('#philosophy-play').addEventListener('click',()=>{if(philosophyTimer)stopPhilosophy();else startPhilosophy();});$('#philosophy-entry').addEventListener('click',e=>{if(e.target.closest('button,a'))stopPhilosophy();});$('#philosophy-return-history').addEventListener('click',()=>{if(philosophyReturnToReader){$('#comparison-reader-dialog').showModal();philosophyReturnToReader=false;$('#philosophy-return-history').textContent='返回历史主线';}else setAppSection('history');});window.addEventListener('pagehide',stopPhilosophy);if(typeof readingIndexCache!=='undefined')readingIndexCache=null;if(params.get('section')==='philosophy')setAppSection('philosophy');else renderPhilosophyAtlas();}
